import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Vidyarambha / Aksharabhyasa source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/21-vidyarambha-profile.md","filePath":"reference/21-vidyarambha-profile.md","lastUpdated":1788519103000}'),d={name:"reference/21-vidyarambha-profile.md"};function n(i,a,s,c,h,l){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="vidyarambha-aksharabhyasa-source-profile" tabindex="-1">Vidyarambha / Aksharabhyasa source profile <a class="header-anchor" href="#vidyarambha-aksharabhyasa-source-profile" aria-label="Permalink to &quot;Vidyarambha / Aksharabhyasa source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The education-commencement profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Commencing education (Aksharabhyasa),” printed page 23 (PDF page 27):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. This is an election for formal commencement; it neither limits when children may learn nor replaces educational, developmental or family judgment.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Most propitious marker: 5th day, 5th month, 5th year</td><td><code>manual_checks</code></td><td>Child age is not a finder input and remains explicit.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are good</td><td><code>allowed_varas</code></td><td>Other weekdays reject the day.</td></tr><tr><td>Eight named Nakshatras are good</td><td><code>allowed_nakshatras</code></td><td>An unlisted active slot-time Nakshatra rejects the candidate.</td></tr><tr><td>Movable and common Rasis are good</td><td><code>allowed_lagnas</code></td><td>The four Chara and four Dvisvabhava Rasis form the slot-time allow-list.</td></tr><tr><td>Prefer forenoon and noon</td><td><code>manual_checks</code></td><td>This is a preference, not an absolute prohibition; it is disclosed rather than converted into the hard Mundana cutoff.</td></tr><tr><td>Leave the 8th vacant; Budha, Shukra and Guru in the 9th counteract adverse influences</td><td><code>manual_checks</code></td><td>Full election-chart occupancy remains practitioner-reviewed.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>Shared samskara exclusions, hard avoid windows, Amrit-Choghadiya and Tithi-family ranking preferences, personal scoring and relative tiers are not established by this citation. MCP exposes <code>muhurta.vidyarambha</code> and every manual requirement; the browser consumes the same generated activity rules.</p>',9)])])}const p=e(d,[["render",n]]);export{u as __pageData,p as default};
